import {
  MousePointer2,
  Hand,
  Circle,
  Triangle,
  Square,
  Shapes,
  Pencil,
  Spline,
  MoveUpRight,
  Waypoints,
  Type,
  Image as ImageIcon,
  LayoutTemplate,
  Settings2,
  Undo2,
  Redo2,
  Download,
  Trash2,
  Maximize,
  type LucideIcon,
} from "lucide-react";
import type { ToolId, ActionId } from "../types";

export interface ToolDef {
  id: ToolId;
  title: string;
  icon: LucideIcon;
  /** 클릭 시 좌측 패널을 여는 도구인지 여부. */
  hasPanel?: boolean;
}

export interface ActionDef {
  id: ActionId;
  title: string;
  icon: LucideIcon;
}

/** 좌측 메인 툴바 도구(기상 전선 도구 제거됨). */
export const MAIN_TOOLS: ToolDef[] = [
  { id: "select", title: "선택 / 이동 (Alt+S)", icon: MousePointer2 },
  { id: "hand", title: "캔버스 이동 (Alt+H)", icon: Hand },
  { id: "ellipse", title: "타원 (Alt+1)", icon: Circle },
  { id: "triangle", title: "삼각형 (Alt+2)", icon: Triangle },
  { id: "rect", title: "사각형 (Alt+3)", icon: Square },
  { id: "shapes", title: "도형 (Alt+4)", icon: Shapes, hasPanel: true },
  { id: "draw", title: "펜 (Alt+5)", icon: Pencil, hasPanel: true },
  { id: "curvedLine", title: "곡선 (Alt+6)", icon: Spline },
  { id: "arrow", title: "화살표 (Alt+7)", icon: MoveUpRight },
  { id: "polypath", title: "선 잇기 (Alt+8)", icon: Waypoints },
  { id: "ctextbox", title: "텍스트 (Alt+T)", icon: Type },
  { id: "images", title: "이미지", icon: ImageIcon, hasPanel: true },
  { id: "templates", title: "템플릿", icon: LayoutTemplate, hasPanel: true },
  { id: "background", title: "캔버스 설정", icon: Settings2, hasPanel: true },
];

/** 상단/보조 액션 버튼. */
export const ACTIONS: ActionDef[] = [
  { id: "undo", title: "실행 취소 (Ctrl+Z)", icon: Undo2 },
  { id: "redo", title: "다시 실행 (Ctrl+Y)", icon: Redo2 },
  { id: "download", title: "내보내기", icon: Download },
  { id: "fullscreen", title: "전체화면", icon: Maximize },
  { id: "clear", title: "초기화", icon: Trash2 },
];

/** 도구 클릭 시 좌측 패널을 여는 도구 목록. */
export const PANEL_TOOLS: ToolId[] = ["shapes", "draw", "images", "templates", "background", "select"];

import { useEffect, useRef, useState } from "react";
import { RgbaStringColorPicker } from "react-colorful";
import { Pipette } from "lucide-react";
import { pickColor, isEyeDropperSupported } from "@/editor/core/eyedropper";

interface ColorPickerProps {
  label?: string;
  value: string;
  onChange: (color: string) => void;
}

/** react-colorful 기반 색상 선택기 팝오버 + 브라우저 내장 스포이트. */
export function ColorPicker({ label, value, onChange }: ColorPickerProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onDoc = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [open]);

  const handleEyedrop = async () => {
    const color = await pickColor();
    if (color) onChange(color);
  };

  return (
    <div className="color-field" ref={ref}>
      {label && <label>{label}</label>}
      <div className="color-field__controls">
        <button
          type="button"
          className="color-swatch"
          style={{ background: value || "transparent" }}
          onClick={() => setOpen((v) => !v)}
          aria-label="색상 선택"
        />
        {isEyeDropperSupported() && (
          <button type="button" className="icon-btn sm" title="스포이트" onClick={handleEyedrop}>
            <Pipette size={14} />
          </button>
        )}
      </div>
      {open && (
        <div className="color-popover">
          <RgbaStringColorPicker color={toRgba(value)} onChange={onChange} />
          <input
            className="color-hex"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            spellCheck={false}
          />
        </div>
      )}
    </div>
  );
}

/** 임의 색 문자열을 react-colorful가 이해하는 rgba 문자열로 정규화. */
function toRgba(value: string): string {
  if (!value || value === "transparent") return "rgba(0,0,0,0)";
  return value;
}

import { Minus, Plus } from "lucide-react";

interface NumberInputProps {
  label?: string;
  value: number;
  min?: number;
  max?: number;
  step?: number;
  onChange: (value: number) => void;
}

/** 증감 버튼이 있는 숫자 입력(기존 custom-number-input 대체). */
export function NumberInput({ label, value, min, max, step = 1, onChange }: NumberInputProps) {
  const clamp = (v: number) => {
    if (min != null && v < min) v = min;
    if (max != null && v > max) v = max;
    return Number(v.toFixed(2));
  };

  return (
    <div className="input-row">
      {label && <label>{label}</label>}
      <div className="number-input">
        <button type="button" className="icon-btn sm" onClick={() => onChange(clamp(value - step))}>
          <Minus size={14} />
        </button>
        <input
          type="number"
          value={value}
          min={min}
          max={max}
          step={step}
          onChange={(e) => onChange(clamp(parseFloat(e.target.value) || 0))}
        />
        <button type="button" className="icon-btn sm" onClick={() => onChange(clamp(value + step))}>
          <Plus size={14} />
        </button>
      </div>
    </div>
  );
}

import { useEditorStore } from "@/editor/store/editorStore";
import { MAIN_TOOLS, ACTIONS } from "@/editor/data/toolbar";
import type { ActionId } from "@/editor/types";

interface ToolbarProps {
  onAction: (action: ActionId) => void;
}

export function Toolbar({ onAction }: ToolbarProps) {
  const activeTool = useEditorStore((s) => s.activeTool);
  const setActiveTool = useEditorStore((s) => s.setActiveTool);
  const canUndo = useEditorStore((s) => s.canUndo);
  const canRedo = useEditorStore((s) => s.canRedo);

  const isDisabled = (id: ActionId) =>
    (id === "undo" && !canUndo) || (id === "redo" && !canRedo);

  return (
    <aside className="toolbar">
      <div className="toolbar__brand" title="Canvas Studio">CS</div>

      <div className="toolbar__group">
        {MAIN_TOOLS.map((tool) => {
          const Icon = tool.icon;
          return (
            <button
              key={tool.id}
              className={`tool-btn${activeTool === tool.id ? " active" : ""}`}
              title={tool.title}
              onClick={() => setActiveTool(tool.id)}
            >
              <Icon size={20} />
            </button>
          );
        })}
      </div>

      <div className="toolbar__spacer" />

      <div className="toolbar__group">
        {ACTIONS.map((action) => {
          const Icon = action.icon;
          return (
            <button
              key={action.id}
              className="tool-btn"
              title={action.title}
              disabled={isDisabled(action.id)}
              onClick={() => onAction(action.id)}
            >
              <Icon size={20} />
            </button>
          );
        })}
      </div>
    </aside>
  );
}

import { useRef } from "react";
import { useEditorCanvas } from "@/editor/hooks/useEditorCanvas";

/** 캔버스를 렌더링하고 Fabric 인스턴스를 초기화하는 스테이지 영역. */
export function CanvasStage() {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasElRef = useRef<HTMLCanvasElement>(null);

  useEditorCanvas(canvasElRef, containerRef);

  return (
    <div className="stage" ref={containerRef}>
      <div className="stage__canvas-holder">
        <canvas ref={canvasElRef} />
      </div>
    </div>
  );
}

import { ZoomIn, ZoomOut, Maximize2 } from "lucide-react";
import { useEditorStore } from "@/editor/store/editorStore";
import { fitZoom } from "@/editor/core/zoom";

export function Footer() {
  const zoom = useEditorStore((s) => s.zoom);
  const setZoom = useEditorStore((s) => s.setZoom);
  const canvas = useEditorStore((s) => s.canvas);

  const handleFit = () => {
    const holder = document.querySelector(".stage") as HTMLElement | null;
    if (canvas && holder) {
      const z = fitZoom(canvas, holder);
      useEditorStore.setState({ zoom: z });
    }
  };

  return (
    <footer className="footer">
      <div className="footer__zoom">
        <button className="icon-btn" title="축소" onClick={() => setZoom(zoom - 0.1)}>
          <ZoomOut size={16} />
        </button>
        <span className="footer__zoom-value">{Math.round(zoom * 100)}%</span>
        <button className="icon-btn" title="확대" onClick={() => setZoom(zoom + 0.1)}>
          <ZoomIn size={16} />
        </button>
        <button className="icon-btn" title="화면 맞춤" onClick={handleFit}>
          <Maximize2 size={16} />
        </button>
      </div>
      <div className="footer__hint">Ctrl+휠: 확대/축소 · 더블클릭: 선/다각형 점 편집</div>
    </footer>
  );
}

import { useEditorStore } from "@/editor/store/editorStore";
import { SHAPE_SVGS } from "@/editor/data/shapes";
