import { useRef, useState } from "react";
import { Upload } from "lucide-react";
import { useEditorStore } from "@/editor/store/editorStore";
import { ColorPicker } from "@/components/common/ColorPicker";
import { NumberInput } from "@/components/common/NumberInput";
import { fabric } from "@/editor/fabric";

/** 캔버스 크기 / 배경색 / 배경 이미지 설정. (기상 주제도/backMap 기능 제거됨) */
export function BackgroundPanel() {
  const canvas = useEditorStore((s) => s.canvas);
  const canvasSize = useEditorStore((s) => s.canvasSize);
  const setCanvasSize = useEditorStore((s) => s.setCanvasSize);
  const [bgColor, setBgColor] = useState<string>("#ffffff");
  const inputRef = useRef<HTMLInputElement>(null);

  const applyBgColor = (color: string) => {
    setBgColor(color);
    if (!canvas) return;
    canvas.backgroundColor = color;
    canvas.requestRenderAll();
    canvas.fire("object:modified");
  };

  const handleBgImage = (files: FileList | null) => {
    if (!files?.[0] || !canvas) return;
    const reader = new FileReader();
    reader.onload = async (e) => {
      const url = e.target?.result as string;
      const img = await fabric.FabricImage.fromURL(url, { crossOrigin: "anonymous" });
      const scaleX = canvas.getWidth() / (img.width || 1);
      const scaleY = canvas.getHeight() / (img.height || 1);
      img.set({ scaleX, scaleY, left: 0, top: 0 });
      canvas.backgroundImage = img;
      canvas.requestRenderAll();
      canvas.fire("object:modified");
    };
    reader.readAsDataURL(files[0]);
  };

  const removeBgImage = () => {
    if (!canvas) return;
    canvas.backgroundImage = undefined;
    canvas.requestRenderAll();
    canvas.fire("object:modified");
  };

  return (
    <div className="panel">
      <h3 className="panel__title">캔버스 설정</h3>

      <div className="panel__section">
        <h4>캔버스 크기</h4>
        <NumberInput
          label="너비"
          value={canvasSize.width}
          min={100}
          step={10}
          onChange={(w) => setCanvasSize({ ...canvasSize, width: w })}
        />
        <NumberInput
          label="높이"
          value={canvasSize.height}
          min={100}
          step={10}
          onChange={(h) => setCanvasSize({ ...canvasSize, height: h })}
        />
      </div>

      <div className="panel__section">
        <h4>배경</h4>
        <ColorPicker label="배경 색상" value={bgColor} onChange={applyBgColor} />
        <button className="btn block" onClick={() => inputRef.current?.click()}>
          <Upload size={16} /> 배경 이미지 첨부
        </button>
        <button className="btn ghost block" onClick={removeBgImage}>
          배경 이미지 제거
        </button>
        <input
          ref={inputRef}
          type="file"
          accept="image/*"
          hidden
          onChange={(e) => handleBgImage(e.target.files)}
        />
      </div>
    </div>
  );
}

import { Eye, EyeOff, ChevronUp, ChevronDown, Trash2 } from "lucide-react";
import { useEditorStore } from "@/editor/store/editorStore";

/** 레이어 목록: 선택 / 표시 토글 / 순서 변경 / 삭제. */
export function LayersPanel() {
  const layers = useEditorStore((s) => s.layers);
  const canvas = useEditorStore((s) => s.canvas);
  const activeObject = useEditorStore((s) => s.activeObject);

  const findObj = (id: string) => canvas?.getObjects().find((o) => o.id === id) ?? null;

  const selectLayer = (id: string) => {
    if (!canvas) return;
    const obj = findObj(id);
    if (!obj || !obj.selectable) return;
    canvas.setActiveObject(obj);
    canvas.requestRenderAll();
    useEditorStore.getState().setActiveTool("select");
  };

  const toggleVisible = (id: string) => {
    if (!canvas) return;
    const obj = findObj(id);
    if (!obj) return;
    obj.visible = !obj.visible;
    canvas.requestRenderAll();
    canvas.fire("object:modified", { target: obj });
  };

  const move = (id: string, dir: "up" | "down") => {
    if (!canvas) return;
    const obj = findObj(id);
    if (!obj) return;
    dir === "up" ? canvas.bringObjectForward(obj) : canvas.sendObjectBackwards(obj);
    canvas.requestRenderAll();
    canvas.fire("object:modified", { target: obj });
  };

  const remove = (id: string) => {
    if (!canvas) return;
    const obj = findObj(id);
    if (!obj) return;
    canvas.remove(obj);
    canvas.discardActiveObject();
    canvas.requestRenderAll();
    canvas.fire("object:modified");
  };

  return (
    <div className="panel layers">
      <h3 className="panel__title">레이어</h3>
      {layers.length === 0 && <p className="panel__hint">아직 객체가 없습니다.</p>}
      <ul className="layer-list">
        {layers.map((layer) => (
          <li
            key={layer.id}
            className={`layer-item${activeObject?.id === layer.id ? " active" : ""}`}
            onClick={() => selectLayer(layer.id)}
          >
            <button
              className="icon-btn sm"
              title="표시/숨김"
              onClick={(e) => {
                e.stopPropagation();
                toggleVisible(layer.id);
              }}
            >
              {layer.visible ? <Eye size={14} /> : <EyeOff size={14} />}
            </button>
            <span className="layer-item__label">{layer.label}</span>
            <span className="layer-item__actions">
              <button className="icon-btn sm" title="앞으로" onClick={(e) => { e.stopPropagation(); move(layer.id, "up"); }}>
                <ChevronUp size={14} />
              </button>
              <button className="icon-btn sm" title="뒤로" onClick={(e) => { e.stopPropagation(); move(layer.id, "down"); }}>
                <ChevronDown size={14} />
              </button>
              <button className="icon-btn sm danger" title="삭제" onClick={(e) => { e.stopPropagation(); remove(layer.id); }}>
                <Trash2 size={14} />
              </button>
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useReducer } from "react";
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  FlipHorizontal,
  FlipVertical,
  BringToFront,
  SendToBack,
  Group as GroupIcon,
  Ungroup,
  Copy,
  Trash2,
  AlignHorizontalJustifyStart,
  AlignHorizontalJustifyCenter,
  AlignHorizontalJustifyEnd,
  AlignVerticalJustifyStart,
  AlignVerticalJustifyCenter,
  AlignVerticalJustifyEnd,
} from "lucide-react";
import { useEditorStore } from "@/editor/store/editorStore";
import { ColorPicker } from "@/components/common/ColorPicker";
import { NumberInput } from "@/components/common/NumberInput";
import { fabric } from "@/editor/fabric";
import { alignObject } from "@/editor/core/align";
import { groupObjects, ungroupObjects } from "@/editor/core/grouping";
import { duplicateActive } from "@/editor/core/clipboard";
import { removeActiveObjects } from "@/editor/core/objects";
import { BorderStyleList, FONT_FAMILIES, borderSectionTypeList } from "@/editor/core/constants";
import { ArrowHeadStyle } from "@/editor/core/constants";
import type { AlignPosition } from "@/editor/types";

const TEXT_TYPES = ["ctextbox"];
const FILL_TYPES = ["ctextbox", "path", "polygon", "circle", "ellipse", "triangle", "rect", "polypath"];

export function SelectionPanel() {
  const canvas = useEditorStore((s) => s.canvas);
  const obj = useEditorStore((s) => s.activeObject);
  const [, bump] = useReducer((x) => x + 1, 0);

  if (!canvas || !obj) return null;
  const type = (obj.type ?? "").toLowerCase();

  const commit = () => {
    canvas.requestRenderAll();
    canvas.fire("object:modified", { target: obj });
    bump();
  };

  const setProp = (props: Record<string, unknown>) => {
    obj.set(props);
    commit();
  };

  const isMulti = type === "activeselection" || type === "group";
  const showFill = FILL_TYPES.includes(type);
  const showBorder = borderSectionTypeList.includes(type);
  const showText = TEXT_TYPES.includes(type);
  const showArrow = type === "arrow";
  const showNeon = ["path", "polygon", "arrow", "curvedline", "ctextbox"].includes(type);

  const align = (pos: AlignPosition) => alignObject(canvas, obj, pos);

  return (
    <div className="panel selection">
      <h3 className="panel__title">{obj.label || "선택 영역"} 설정</h3>

      {showText && (
        <div className="panel__section">
          <h4>텍스트</h4>
          <div className="style-row">
            <button className={`icon-btn${obj.get("fontWeight") === "bold" ? " active" : ""}`} title="굵게"
              onClick={() => setProp({ fontWeight: obj.get("fontWeight") === "bold" ? "normal" : "bold" })}>
              <Bold size={16} />
            </button>
            <button className={`icon-btn${obj.get("fontStyle") === "italic" ? " active" : ""}`} title="기울임"
              onClick={() => setProp({ fontStyle: obj.get("fontStyle") === "italic" ? "normal" : "italic" })}>
