            </button>
            <button className={`icon-btn${obj.get("underline") ? " active" : ""}`} title="밑줄"
              onClick={() => setProp({ underline: !obj.get("underline") })}>
              <Underline size={16} />
            </button>
            <button className={`icon-btn${obj.get("linethrough") ? " active" : ""}`} title="취소선"
