  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.layer-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border-radius: var(--radius-sm);
  cursor: pointer;
}

.layer-item:hover {
  background: var(--surface-2);
}

.layer-item.active {
  background: var(--primary-soft);
}

.layer-item__label {
  flex: 1;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.layer-item__actions {
  display: flex;
  gap: 0;
  opacity: 0;
  transition: opacity 0.15s;
}

.layer-item:hover .layer-item__actions,
.layer-item.active .layer-item__actions {
  opacity: 1;
}

/* ============ Stage ============ */
.stage {
  flex: 1;
  overflow: auto;
  display: grid;
  place-items: center;
  padding: 32px;
  background: var(--bg);
  background-image: radial-gradient(circle, #dfe3e8 1px, transparent 1px);
  background-size: 20px 20px;
}

.stage__canvas-holder {
  box-shadow: var(--shadow);
  background: #fff;
  line-height: 0;
}

.canvas-container {
  box-shadow: var(--shadow);
}

/* ============ Footer ============ */
.footer {
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  background: var(--surface);
  border-top: 1px solid var(--border);
}

.footer__zoom {
  display: flex;
  align-items: center;
  gap: 4px;
}

.footer__zoom-value {
  min-width: 48px;
  text-align: center;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.footer__hint {
  font-size: 12px;
  color: var(--text-muted);
}

/* ============ Modal ============ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(17, 24, 39, 0.5);
  display: grid;
  place-items: center;
  z-index: 100;
}

.modal {
  width: 560px;
  max-width: 92vw;
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.modal__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--border);
}

.modal__header h3 {
  font-size: 16px;
}

.modal__body {
  display: flex;
  gap: 20px;
  padding: 20px;
}

.modal__preview {
  flex: 1;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  display: grid;
  place-items: center;
  min-height: 180px;
  overflow: hidden;
}

.modal__preview img {
  max-width: 100%;
  max-height: 220px;
}

.modal__options {
  width: 200px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.modal__options label {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 6px;
}

.modal__options input {
  padding: 8px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
}

.format-toggle {
  display: flex;
  gap: 6px;
}

.format-toggle .btn {
  flex: 1;
  padding: 6px;
}

.modal__footer {
  padding: 16px 20px;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: flex-end;
}

